export function sandboxedSelfModification(policyEvaluator, safetyValidator) {
  const sandbox = [];
  return {
    simulateModification: (policy) => {
      const simulationResult = policyEvaluator(policy);
      sandbox.push(simulationResult);
      return simulationResult;
    },
    validateSafety: (modification) => {
      return safetyValidator(modification);
    },
    applyModification: (modification) => {
      if (sandbox.includes(modification) && safetyValidator(modification)) {
        return modification;
      }
      throw new Error('Modification failed safety checks or was not simulated.');
    }
  };
}